,{
"ClauseCode":"1001819"
,"ClauseContent":"INSTITUTE RADIOACTIVE CONTAMINATION EXCLUSION CLAUSE 1/10/90"
,"ClauseDescription":"<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">This clause shall be paramount and shall override anything contained in this insurance inconsistent therewith. </span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">1. In no case shall this insurance cover loss, damage, liability or expense directly or indirectly caused by, contributed to by or arising from: </span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">   1.1. ionising radiations from or contamination by radioactivity from any nuclear fuel or from any nuclear waste or from the combustion of nuclear fuel, </span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">   1.2. the radioactive, toxic, explosive or other hazardous or contaminating properties of any nuclear installation, reactor or other nuclear assembly or nuclear component thereof, </span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">   1.3. any weapon of war employing atomic or nuclear fission and/or fusion or other like reaction or radioactive force or matter.</span></span></p>"
,"ClauseTitle":"INSTITUTE RADIOACTIVE CONTAMINATION EXCLUSION CLAUSE 1/10/90"
,"ClauseType":"MARINE"
,"KodeSection":"1"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
}
,{
"ClauseCode":"1012357"
,"ClauseContent":"NEREC (0.1.01.89) WITH JAPANESE AMENDMENT, (01.04.89) INCLUSION OF NUCLEAR FUELS IN TRANSIT"
,"ClauseDescription":"<div style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">1.1 This contract excludes nuclear energy risks whether written directly or by war of reinsurance or via pools or associations. Under this contract the term &ldquo;nuclear energy risks&rdquo; means any first or third party insurance (other than workers&rsquo; compensation or employers&rsquo; liability) in respect of:<br />\n1.1.1 nuclear reactors and nuclear power stations or plant;<br />\n1.1.2 any other premises or facilities concerned with<br />\n1.1.2.1 the production of nuclear energy or<br />\n1.1.2.2 the production or storage or handling of nuclear fuels or nuclear waste;<br />\n1.1.3 any other premises or facilities eligible for insurance by any local nuclear pool or association but only to the extent of the requirements of the local pool or association;<br />\n1.1.4 nuclear or radioactive fuel, or nuclear or radioactive waste. 　　　<br />\n1.2 However, this exclusion shall not apply<br />\n1.2.1 to any insurance or reinsurance in respect of the construction, erection or installation of buildings, plant and other property (including contractor&rsquo;s plant and equipment used in connection therewith):<br />\n1.2.1.1 for the storage of nuclear fuel &ndash; prior to the commencement of storage<br />\n1.2.1.2 as regards reactor installations &ndash; prior to the commencement of loading of nuclear fuel into the reactor, or prior to the initial criticality, depending on the commencement of the insurance or reinsurance of the relevant local nuclear pool or association;<br />\n1.2.2 to any machinery breakdown or other engineering insurance or reinsurance not coming within the scope of 6.2.1 above, nor affording coverage in the &ldquo;high radioactivity&rdquo; zone;<br />\n1.2.3 to any insurance or reinsurance in respect of the hulls of ships, aircraft or other conveyances;<br />\n1.2.4 to any insurance or reinsurance in respect of loss of or damage to (including any expenses incurred therewith) nuclear or radioactive fuel or nuclear or radioactive waste while in transit or storage as cargo, other than while being processed or while in storage at the reactor installation or any other final destination concerned with production, storage or handling of nuclear fuel or nuclear waste.</span></span></div>"
,"ClauseTitle":"NEREC (0.1.01.89) WITH JAPANESE AMENDMENT, (01.04.89) INCLUSION OF NUCLEAR FUELS IN TRANSIT"
,"ClauseType":"MARINE"
,"KodeSection":"1"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
}
