,{
"ClauseCode":"1016225"
,"ClauseContent":"POLITICAL RISK EXCLUSION CLAUSE"
,"ClauseDescription":"<div style=\"text-align: justify;\"><span style=\"font-size:9px;\"><span style=\"font-family:Times New Roman,Times,serif;\">Loss of property due to political risk is hereby excluded.<br />\nPolitical Risk are defined as follow:<br />\nConfiscation, expropriation, nationalization, commandeering, requisition or destruction of or damage to property by order of the government de jure or de facto or any public, municipal or local authority of the country or area in which the property is situated, seizure or destruction under quarantine or customs regulation.</span></span></div>"
,"ClauseTitle":"POLITICAL RISK EXCLUSION CLAUSE"
,"ClauseType":"MARINE"
,"KodeSection":"1"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
}
